// Resolve o macro_tema recebido (numero '11', ou texto 'inovacao', ou rotulo exato) para o rotulo EXATO do enum.
const LABELS = ['1. AGRONEGÓCIO','2. COMUNICAÇÃO','3. DIVERSIDADE E INCLUSÃO','4. ECONOMIA / POLÍTICA','5. EDUCAÇÃO','6. EMPREENDEDORISMO','7. ESPORTE','8. ÉTICA','9. GESTÃO','10. GESTÃO DE PESSOAS','11. INOVAÇÃO','12. MOTIVAÇÃO','13. SAÚDE','14. SIPAT','15. SUSTENTABILIDADE','16. VENDAS','17. CONSCIENTIZAÇÃO (MESES)','18. OUTROS','19. LIDERANÇA','20. COMPORTAMENTO','21. COOPERATIVISMO','22. EXPERIÊNCIA E ATENDIMENTO','23. DATAS COMEMORATIVAS','24. FINANÇAS','25. PROTAGONISMO FEMININO'];

const wh = items[0].json || {};
const raw = String((wh.query && wh.query.macro_tema) || (wh.body && wh.body.macro_tema) || '').trim();
const norm = s => String(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');

let label = '';
if (/^\d+$/.test(raw)) {
  label = LABELS.find(l => l.split('.')[0] === raw) || '';
} else if (raw) {
  const rn = norm(raw);
  label = LABELS.find(l => norm(l) === rn)
       || LABELS.find(l => norm(l.replace(/^\d+\.\s*/, '')) === rn)
       || LABELS.find(l => norm(l).indexOf(rn) !== -1)
       || '';
}
if (!label) label = raw; // deixa cru; a busca pode simplesmente nao achar

return [{ json: { temaLabel: label, temaRaw: raw } }];

// Entradas: "Redis Keys" (scores) + "HubSpot Search" (subconjunto filtrado por macro tema) + "Resolve Tema".
// Saida: CSV do ranking do macro tema (avaliados por pontuacao desc; pendentes por ultimo).

// 1) Indexa scores do Redis por id
const scores = {};
function pushParsed(v) {
  let r = v;
  if (typeof v === 'string') { try { r = JSON.parse(v); } catch (e) { return; } }
  if (r && r.id) scores[String(r.id)] = r;
}
for (const it of items) {
  const j = it.json || {};
  if (j.value !== undefined && (j.key || j.name)) {
    pushParsed(j.value); // formato {key, value}
  } else {
    for (const [k, v] of Object.entries(j)) {
      if (k.indexOf('pcur:pal:') === 0) pushParsed(v); // formato {chave: valor, ...}
    }
  }
}

// 2) Subconjunto filtrado no HubSpot (o "primeiro filtro")
const search = $('HubSpot Search').first().json;
const results = (search && search.results) || [];
const temaLabel = $('Resolve Tema').first().json.temaLabel || '';

const linhas = results.map(c => {
  const p = c.properties || {};
  const nome = ((p.firstname || '') + ' ' + (p.lastname || '')).trim();
  const sc = scores[String(c.id)];
  return {
    id: c.id,
    nome,
    macro_tema: p.macro_tema_contato || temaLabel,
    scored: !!sc,
    pontuacao_total: sc ? sc.pontuacao_total : '',
    compatibilidade: sc ? sc.compatibilidade : '',
    notas: sc ? (sc.notas || {}) : {},
    wiki_url: sc ? (sc.wiki_url || '') : ''
  };
});

// 3) Ordena: avaliados primeiro (pontuacao desc), pendentes por ultimo
linhas.sort((a, b) => {
  if (a.scored !== b.scored) return a.scored ? -1 : 1;
  return (b.pontuacao_total || 0) - (a.pontuacao_total || 0);
});

// 4) CSV
function esc(v) {
  const s = String(v == null ? '' : v);
  return /[",\n;]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
}
const header = ['rank', 'nome', 'macro_tema', 'status', 'pontuacao_total', 'compatibilidade_pct', 'quem_e', 'defende', 'entrega', 'pra_quem', 'comprova', 'raiox', 'hubspot_id', 'wiki_url'];
const out = [header.join(',')];
linhas.forEach((r, i) => {
  const n = r.notas || {};
  out.push([
    i + 1, esc(r.nome), esc(r.macro_tema), r.scored ? 'avaliado' : 'pendente',
    r.pontuacao_total, r.compatibilidade,
    n.quem_e != null ? n.quem_e : '', n.defende != null ? n.defende : '', n.entrega != null ? n.entrega : '',
    n.pra_quem != null ? n.pra_quem : '', n.comprova != null ? n.comprova : '', n.raiox != null ? n.raiox : '',
    r.id, esc(r.wiki_url)
  ].join(','));
});
const csv = out.join('\n');
const avaliados = linhas.filter(r => r.scored).length;

return [{ json: { macro_tema: temaLabel, total: linhas.length, avaliados, pendentes: linhas.length - avaliados, csv } }];
